module div_8bit (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    input res_ready,
    output reg res_valid,
    output [15:0] result
);

    // Internal signals
    reg [7:0] dividend_abs;
    reg [7:0] divisor_extend;
    reg [8:0] NEG_DIVISOR;
    reg [9:0] all_sub_result;
    reg [8:0] sub_result;
    reg [9:0] REMAINDER;
    reg [15:0] SR;
    reg [7:0] QUOTIENT;
    reg CO;
    reg [8:0] mux_result;
    reg [6:0] quotient_shift;
    reg start_cnt;

    // Logic implementations
    assign divisor_extend = (sign && (divisor[7])) ? {1'b1, divisor} : {1'b0, divisor};
    assign NEG_DIVISOR = divisor_extend;
    assign all_sub_result = REMAINDER + NEG_DIVISOR;
    assign sub_result = all_sub_result[8:0];
    assign REMAINDER = SR[15:8];
    assign QUOTIENT = SR[7:0];
    assign CO = all_sub_result[9];
    assign mux_result = (CO) ? sub_result : REMAINDER;
    assign quotient_shift = SR[15:8];
    assign dividend_abs = (sign && (dividend[7])) ? ~dividend + 1 : dividend;

    // Sequential logic implementations
    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            SR <= 16'b0;
            start_cnt <= 1'b0;
        end else if (opn_valid && !start_cnt) begin
            SR <= {dividend_abs, 1'b0};
            start_cnt <= 1'b1;
        end else if (start_cnt) begin
            if (CO) begin
                SR <= {mux_result[8:1], 1'b0, CO, 1'b0};
            end else begin
                SR <= {mux_result[8:1], 1'b0, CO, 1'b0};
            end
        end
    end

    // Combinational logic implementation for res_valid
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            res_valid <= 1'b0;
        end else if (start_cnt && (SR[15:8] == 8'b0)) begin
            res_valid <= 1'b1;
        end else if (res_valid && res_ready) begin
            res_valid <= 1'b0;
        end
    end

    // Final result construction
    assign final_remainer = (sign && (dividend[7])) ? ~REMAINDER + 1 : REMAINDER;
    assign final_quotient = (sign && ((dividend[7]) ^ (divisor[7]))) ? ~QUOTIENT + 1 : QUOTIENT;
    assign is_final_quotient_sign = sign & (dividend[7] ^ divisor[7]);
    assign result = {final_remainer, final_quotient};

endmodule
